#pragma once

/**
 * @file
 * @brief Discrete logarithm modulo any `m < 2^64` (least `x >= 0` with
 *        `a^x ≡ b (mod m)`), multiplicative order, and primitive roots.
 *
 * The coprime core is Pohlig–Hellman inside the cyclic group generated by `a`:
 * the order of `a` is found from the factorization of Carmichael's `λ(m)`, the
 * logarithm is solved one prime power of that order at a time, each digit by
 * baby-step giant-step in a subgroup of prime order, and the pieces are joined by
 * the Chinese remainder theorem. A non-coprime `a` is first reduced by dividing
 * out `gcd(a, m)` step by step.
 *
 * All 64-bit moduli use the same engines on every target; atl::uint128
 * supplies wide arithmetic through native integers or software limbs.
 */

#include <atl/config.hpp>
#include <atl/ds/flat_hash_map.hpp>
#include <atl/nt/basic.hpp>
#include <atl/nt/crt.hpp>
#include <atl/nt/modular.hpp>
#include <atl/nt/montgomery.hpp>
#include <atl/nt/sieve.hpp>
#include <atl/types/alias.hpp>
#include <atl/utils/assert.hpp>
#include <algorithm>
#include <bit>
#include <concepts>
#include <cstddef>
#include <functional>
#include <limits>
#include <numeric>
#include <optional>
#include <type_traits>
#include <utility>
#include <vector>

namespace atl {
	namespace detail {
		/**
		 * @brief The arithmetic a discrete-log engine runs on: residues in some
		 *        internal form (a bijection of `[0, mod)`, so forms can be hashed and
		 *        compared directly), with `to_form`/`from_form`, `one()` and `mul`.
		 */
		template<typename Engine>
		concept modular_multiplier = requires(Engine const e, uint64 x) {
			{ e.mod() } -> std::same_as<uint64>;
			{ e.to_form(x) } -> std::same_as<uint64>;
			{ e.from_form(x) } -> std::same_as<uint64>;
			{ e.one() } -> std::same_as<uint64>;
			{ e.mul(x, x) } -> std::same_as<uint64>;
		};

		/** @brief A Barrett reducer: @ref atl::barrett or @ref atl::barrett64. */
		template<typename Reducer>
		concept barrett_reducer = std::constructible_from<Reducer, decltype(std::declval<Reducer const &>().mod())>
							   && requires(Reducer const r, decltype(r.mod()) x) {
									  { r.mod() } -> unsigned_integral;
									  requires(sizeof(decltype(r.mod())) <= sizeof(uint64));
									  { r.mul(x, x) } -> std::same_as<decltype(r.mod())>;
								  };

		/**
		 * @brief Plain residues multiplied through a Barrett reducer: @ref atl::barrett
		 *        (32-bit) or @ref atl::barrett64. Forms are the residues themselves.
		 */
		template<barrett_reducer Reducer>
		class barrett_multiplier {
			using value = decltype(std::declval<Reducer const &>().mod());
			Reducer reducer_;

			static constexpr value checked_modulus(uint64 m) {
				atl_assert(m >= 1 && m <= (std::numeric_limits<value>::max)());
				return value(m);
			}

		public:
			/** @pre `m` fits the reducer's width (asserted). */
			constexpr explicit barrett_multiplier(uint64 m) : reducer_(checked_modulus(m)) {}

			constexpr uint64 mod() const { return reducer_.mod(); }

			/** @brief The form of @p x: itself. */
			constexpr uint64 to_form(uint64 x) const { return x; }

			/** @brief The residue of @p x: itself. */
			constexpr uint64 from_form(uint64 x) const { return x; }

			/** @brief 1 (0 modulo 1). */
			constexpr uint64 one() const { return 1 % reducer_.mod(); }

			/**
			 * @brief `a·b mod m`.
			 * @pre `a, b < m`.
			 */
			constexpr uint64 mul(uint64 a, uint64 b) const { return reducer_.mul(value(a), value(b)); }
		};

		/** @brief `x^e` for a form `x` of @p engine. */
		template<modular_multiplier Engine>
		constexpr uint64 engine_power(Engine const &engine, uint64 x, uint64 e) {
			uint64 result = engine.one();
			// Shift before deciding to square: MSVC 14.44 x86 miscompiled the `for (; e > 0; e >>= 1)` form with a
			// trailing `if (e > 1)` square, returning one() for every exponent of 2^33 and up (montgomery64 engine).
			while (e != 0) {
				if (e & 1) result = engine.mul(result, x);
				e >>= 1;
				if (e != 0) x = engine.mul(x, x);
			}
			return result;
		}

		/** @brief `ceil(sqrt(n))` for any 64-bit `n`. */
		constexpr uint64 ceil_sqrt(uint64 n) {
			// least r with r·r >= n, by bisection over [0, 2^32]; mid < 2^32, so mid·mid fits
			uint64 lo = 0, hi = uint64(1) << 32;
			while (lo < hi) {
				uint64 const mid = lo + (hi - lo) / 2;
				if (mid * mid >= n)
					hi = mid;
				else
					lo = mid + 1;
			}
			return lo;
		}

		/**
		 * @brief Carmichael's `λ(m)` (the exponent of the unit group mod `m`) as a
		 *        factorization: the lcm of `λ(p^e)` over `p^e ‖ m`, with
		 *        `λ(p^e) = p^(e-1)·(p-1)` for odd `p` and `λ(2) = 1`, `λ(4) = 2`,
		 *        `λ(2^e) = 2^(e-2)`.
		 */
		constexpr std::vector<prime_factor> carmichael_factorization(uint64 m) {
			std::vector<prime_factor> lambda;
			auto const raise = [&](uint64 p, uint64 e) {
				if (e == 0) return;
				for (auto &f : lambda)
					if (f.prime == p) {
						f.exponent = (std::max)(f.exponent, e);
						return;
					}
				lambda.push_back({p, e});
			};
			for (auto const &[p, e] : factorization(m)) {
				if (p == 2) {
					raise(2, e == 1 ? 0 : e == 2 ? 1
												 : e - 2);
					continue;
				}
				raise(p, e - 1);
				for (auto const &[q, f] : factorization(p - 1)) raise(q, f);
			}
			std::ranges::sort(lambda, {}, &prime_factor::prime);
			return lambda;
		}

		/**
		 * @brief The order of the form @p a (a unit) and its factorization, by
		 *        stripping primes from `λ(m)` while `a` still powers to one.
		 */
		template<modular_multiplier Engine>
		constexpr std::vector<prime_factor> order_factorization(Engine const &engine, uint64 a) {
			std::vector<prime_factor> order = carmichael_factorization(engine.mod());
			uint64 n = 1;
			for (auto const &[p, e] : order)
				for (uint64 i = 0; i < e; ++i) n *= p;
			for (auto &[p, e] : order) {
				while (e > 0 && engine_power(engine, a, n / p) == engine.one()) {
					n /= p;
					--e;
				}
			}
			std::erase_if(order, [](prime_factor const &f) { return f.exponent == 0; });
			return order;
		}

		/**
		 * @brief Baby-step giant-step table for logarithms to a base of known order:
		 *        `log(c)` in `[0, order)` with `base^log(c) = c`, or none.
		 */
		template<modular_multiplier Engine>
		class bsgs_table {
			Engine const &engine_;
			flat_hash_map<uint64, uint32> baby_;
			uint64 step_, giant_, order_, max_giant_step_;

			static constexpr std::size_t table_size(uint64 order) {
				uint64 const count = ceil_sqrt(order);
				atl_assert(count <= (std::numeric_limits<std::size_t>::max)());
				return static_cast<std::size_t>(count);
			}

		public:
			/**
			 * @brief Tabulates `base^j` for `j < ceil(sqrt(order))`.
			 * @pre `base` (a form) has order exactly `order`, `1 <= order`.
			 * @complexity O(sqrt(order)) multiplications and insertions
			 */
			bsgs_table(Engine const &engine, uint64 base, uint64 order)
				: engine_(engine), baby_(table_size(order)), step_(ceil_sqrt(order)), order_(order),
				  max_giant_step_((order - 1) / step_) {
				// baby indices are uint32: step_ <= 2^32 since order < 2^64
				atl_assert(step_ <= (uint64(1) << 32));
				uint64 power = engine.one();
				for (uint64 j = 0; j < step_; ++j) {
					baby_.insert(power, uint32(j)); // the order is >= step_, so powers are distinct
					power = engine.mul(power, base);
				}
				// power = base^step_; the giant stride divides by it
				giant_ = engine.to_form(inverse_mod(engine.from_form(power), engine.mod()));
			}

			/**
			 * @brief The logarithm of the form @p c to the table's base, in `[0, order)`,
			 *        or none when @p c is not a power of the base.
			 * @complexity O(sqrt(order)) multiplications and lookups
			 */
			std::optional<uint64> log(uint64 c) const {
				for (uint64 i = 0; i <= max_giant_step_; ++i) {
					auto const it = baby_.find(c);
					if (it != baby_.end() && it->second < order_ - i * step_) return i * step_ + it->second;
					c = engine_.mul(c, giant_);
				}
				return std::nullopt;
			}
		};

		/**
		 * @brief Least `y >= 0` with `a^y = t` for unit forms `a`, `t`, by
		 *        Pohlig–Hellman over the order of `a`; none when `t` is not a power
		 *        of `a`.
		 *
		 * @complexity O(Σ e·(sqrt(q) + log m)) over `q^e ‖ ord(a)`, plus factoring
		 *             `m` and `p - 1` for `p | m`
		 */
		template<modular_multiplier Engine>
		std::optional<uint64> pohlig_hellman(Engine const &engine, uint64 a, uint64 t) {
			std::vector<prime_factor> const order = order_factorization(engine, a);
			uint64 n = 1;
			for (auto const &[q, e] : order)
				for (uint64 i = 0; i < e; ++i) n *= q;
			std::vector<congruence<uint64>> pieces;
			for (auto const &[q, e] : order) {
				uint64 q_power = 1;
				for (uint64 i = 0; i < e; ++i) q_power *= q;
				uint64 const h = engine_power(engine, a, n / q_power);	   // order q^e
				uint64 const s = engine_power(engine, t, n / q_power);	   // in <h> if t in <a>
				uint64 const gamma = engine_power(engine, h, q_power / q); // order q
				uint64 const h_inverse = engine.to_form(inverse_mod(engine.from_form(h), engine.mod()));
				bsgs_table<Engine> const table(engine, gamma, q);
				// x = d_0 + d_1·q + … ; digit k from (s·h^-x)^(q^(e-1-k)) = gamma^d_k
				uint64 x = 0, digit_weight = 1, shift = engine.one(); // shift = h^-x
				for (uint64 k = 0; k < e; ++k) {
					uint64 const c = engine_power(engine, engine.mul(s, shift), q_power / q / digit_weight);
					auto const d = table.log(c);
					if (!d) return std::nullopt;
					x += *d * digit_weight;
					shift = engine.mul(shift, engine_power(engine, h_inverse, *d * digit_weight));
					digit_weight *= q;
				}
				pieces.push_back({x, q_power});
			}
			auto const joined = chinese_remainder(pieces);
			atl_assert(joined.has_value()); // coprime moduli are always consistent
			uint64 const y = joined->residue;
			if (engine_power(engine, a, y) != t) return std::nullopt;
			return y;
		}

		/**
		 * @brief The non-coprime reduction around a coprime solver: checks the
		 *        exponents below 64 directly, then divides `gcd(a, m)` out of
		 *        `a^x ≡ b (mod m)` until `a` is a unit (at most log2 m steps, each
		 *        shifting `x` by one), and hands the unit equation to @p solve with an
		 *        engine for the reduced modulus.
		 */
		template<typename Solve>
			requires std::invocable<Solve const &, uint64, uint64, uint64>
				  && std::same_as<std::invoke_result_t<Solve const &, uint64, uint64, uint64>, std::optional<uint64>>
		constexpr std::optional<uint64> discrete_log_reduced(uint64 a, uint64 b, uint64 m, Solve const &solve) {
			atl_assert(m >= 1);
			a %= m;
			b %= m;
			uint64 power = 1 % m;
			for (uint64 x = 0; x < 64; ++x) {
				if (power == b) return x;
				power = mul_mod_unchecked(power, a, m);
			}
			// x >= 64 >= the number of reduction steps below
			uint64 shift = 0, coefficient = 1 % m;
			for (uint64 g = std::gcd(a, m); g != 1; g = std::gcd(a, m)) {
				if (b % g != 0) return std::nullopt;
				m /= g;
				b /= g;
				coefficient = mul_mod_unchecked(coefficient % m, (a / g) % m, m);
				++shift;
			}
			// coefficient·a^(x - shift) ≡ b (mod m); the coefficient is a unit
			uint64 const target = mul_mod_unchecked(b % m, inverse_mod(coefficient % m, m), m);
			auto const y = std::invoke(solve, a % m, target, m);
			if (!y) return std::nullopt;
			return *y + shift;
		}

		/**
		 * @brief Dispatches @p body on the arithmetic engine for modulus @p m:
		 *        Montgomery arithmetic for odd `m >= 2^32`, @ref atl::barrett for
		 *        `m < 2^32`, @ref atl::barrett64 otherwise (Montgomery needs odd `m`).
		 *
		 */
		template<typename Body>
			requires std::invocable<Body const &, barrett_multiplier<barrett> const &>
				  && std::invocable<Body const &, barrett_multiplier<barrett64> const &>
				  && std::invocable<Body const &, montgomery64 const &>
				  && std::same_as<std::invoke_result_t<Body const &, barrett_multiplier<barrett> const &>,
								  std::invoke_result_t<Body const &, barrett_multiplier<barrett64> const &>>
				  && std::same_as<std::invoke_result_t<Body const &, barrett_multiplier<barrett> const &>,
								  std::invoke_result_t<Body const &, montgomery64 const &>>
		constexpr auto with_engine(uint64 m, Body const &body) {
			if (m < (uint64(1) << 32)) return std::invoke(body, barrett_multiplier<barrett>(m));
			if (m & 1) return std::invoke(body, montgomery64(m));
			return std::invoke(body, barrett_multiplier<barrett64>(m));
		}
	}

	/**
	 * @brief The least `x >= 0` with `a^x ≡ b (mod m)`, or none; any `m >= 1`.
	 *
	 * `0^0 = 1`, and modulo 1 every value is 0, so `x = 0` there. `a` need not be
	 * coprime to `m`: small exponents are checked directly, then `gcd(a, m)` is
	 * divided out until `a` is a unit, and the unit equation is solved by
	 * Pohlig–Hellman in the group generated by `a`.
	 *
	 * @note Not constexpr (baby-step tables use atl::flat_hash_map with a runtime seed).
	 *
	 * @param a Base, reduced modulo m.
	 * @param b Target, reduced modulo m.
	 * @param m Positive modulus.
	 * @return Least exponent, or std::nullopt when the target is unreachable.
	 * @pre `m >= 1` (asserted).
	 * @complexity Expected O(Σ e·(sqrt(q) + log m)) over the prime powers `q^e` of the order
	 *             of `a` (worst case O(sqrt(m)) for a prime order near `m`), plus
	 *             the Pollard-rho factorizations of `m` and of `p - 1` for `p | m`.
	 *             O(max sqrt(q)) table storage; allocation failure propagates.
	 */
	[[nodiscard]] inline std::optional<uint64> discrete_log(uint64 a, uint64 b, uint64 m) {
		return detail::discrete_log_reduced(a, b, m, [](uint64 base, uint64 target, uint64 mod) {
			return detail::with_engine(mod, [&]<detail::modular_multiplier Engine>(Engine const &engine) {
				return detail::pohlig_hellman(engine, engine.to_form(base), engine.to_form(target));
			});
		});
	}

	/**
	 * @brief The multiplicative order of `a` modulo `m`: the least `k >= 1` with
	 *        `a^k ≡ 1 (mod m)`.
	 * @param a Unit, reduced modulo m.
	 * @param m Positive modulus.
	 * @return The order, with value 1 modulo 1.
	 * @pre `m >= 1` and `gcd(a, m) == 1` (asserted).
	 * @complexity the Pollard-rho factorizations of `m` and of `p - 1` for `p | m`,
	 *             plus O(log² m) multiplications
	 */
	[[nodiscard]] constexpr uint64 multiplicative_order(uint64 a, uint64 m) {
		atl_assert(m >= 1);
		atl_assert(std::gcd(a % m, m) == 1);
		if (m == 1) return 1;
		return detail::with_engine(m, [&]<detail::modular_multiplier Engine>(Engine const &engine) {
			uint64 order = 1;
			for (auto const &[q, e] : detail::order_factorization(engine, engine.to_form(a % m)))
				for (uint64 i = 0; i < e; ++i) order *= q;
			return order;
		});
	}

	/**
	 * @brief The least primitive root modulo the prime `p`: a generator of the
	 *        unit group, tested candidate by candidate against the prime factors of
	 *        `p - 1` (`g` generates iff `g^((p-1)/q) ≠ 1` for each of them).
	 * @param p Prime modulus.
	 * @return The least positive generator; 1 for p=2.
	 * @pre `p` prime (asserted).
	 * @complexity factoring `p - 1`, plus O(log p) multiplications per prime factor
	 *             per candidate; at most `p - 1` candidates are examined.
	 */
	[[nodiscard]] constexpr uint64 primitive_root(uint64 p) {
		atl_assert(is_prime(p));
		if (p == 2) return 1;
		std::vector<prime_factor> const factors = factorization(p - 1);
		return detail::with_engine(p, [&]<detail::modular_multiplier Engine>(Engine const &engine) {
			for (uint64 g = 2;; ++g) {
				uint64 const form = engine.to_form(g);
				bool const is_generator = std::ranges::all_of(factors, [&](prime_factor const &f) {
					return detail::engine_power(engine, form, (p - 1) / f.prime) != engine.one();
				});
				if (is_generator) return g;
			}
		});
	}
}
